<?php

namespace Tests\Feature\Core\Security;

use PHPUnit\Framework\Attributes\Group;
use PHPUnit\Framework\Attributes\Test;
use PHPUnit\Framework\TestCase;

/**
 * The example nginx/Apache configs use public/ as the web root. Everything the pages link to
 * must either live inside it or be mapped in explicitly:
 *   - assets/ is generated by "yarn build" (Grunt) from resources/assets into public/assets, so the
 *     configs need no mapping for it, and the sources must not be reachable from the web root;
 *   - favicon.ico and robots.txt live in public/;
 *   - the logo files directly inside uploads/ are outside public/ and are mapped in explicitly while
 *     the private uploads subdirectories stay denied.
 */
#[Group('security')]
final class ExampleWebServerConfigStaticTreesTest extends TestCase
{
    #[Test]
    public function it_keeps_asset_sources_outside_the_web_root_and_builds_into_it(): void
    {
        /* Arrange */
        $gitignore = (string) file_get_contents(ROOT_PATH . '/public/assets/.gitignore');

        /* Act / Assert */
        self::assertDirectoryExists(ROOT_PATH . '/resources/assets/core/scss', 'asset sources live in resources/assets.');
        self::assertFileExists(ROOT_PATH . '/resources/assets/core/js/scripts.js');
        self::assertFileExists(ROOT_PATH . '/resources/assets/invoiceplane/invoiceplane.theme');
        self::assertDirectoryDoesNotExist(ROOT_PATH . '/public/assets/core/scss', 'sources must not be served.');
        self::assertDirectoryDoesNotExist(ROOT_PATH . '/public/assets/invoiceplane/sass', 'sources must not be served.');
        self::assertMatchesRegularExpression('/^\*$/m', $gitignore, 'public/assets holds build output only.');
        self::assertFileExists(ROOT_PATH . '/public/favicon.ico');
        self::assertFileExists(ROOT_PATH . '/public/robots.txt');
    }

    #[Test]
    public function it_does_not_map_assets_favicon_or_robots_outside_the_nginx_root(): void
    {
        /* Arrange */
        $conf = (string) file_get_contents(ROOT_PATH . '/resources/docker/nginx/invoiceplane.conf');

        /* Act / Assert */
        self::assertMatchesRegularExpression('#root\s+\S+/public;#', $conf);
        self::assertDoesNotMatchRegularExpression('#alias\s+\S+/(assets|favicon\.ico|robots\.txt)#', $conf, 'those files are inside public/, an alias would point outside the root.');
    }

    #[Test]
    public function it_serves_only_image_files_directly_inside_uploads_and_keeps_the_private_subdirectories_denied(): void
    {
        /* Arrange */
        $conf = (string) file_get_contents(ROOT_PATH . '/resources/docker/nginx/invoiceplane.conf');

        /* Act */
        preg_match('#location\s+~\s+\^/uploads/\(\[\^/\]\+\\\\\.\(\?:([^)]*)\)\)\$\s*\{[^}]*alias#', $conf, $m);
        $extensions = isset($m[1]) ? explode('|', $m[1]) : [];

        /* Assert */
        self::assertNotSame([], $extensions, 'nginx must map the logo files directly inside uploads/.');
        self::assertSame([], array_intersect($extensions, ['php', 'html', 'csv', 'xml', 'pdf']), 'only image extensions may be served from uploads/.');
        foreach (['archive', 'customer_files', 'import', 'temp'] as $private) {
            self::assertMatchesRegularExpression('#location\s+\^~\s+/uploads/' . $private . '/\s*\{\s*deny all;#', $conf, "uploads/{$private} must stay denied.");
        }
    }

    #[Test]
    public function it_keeps_the_apache_example_free_of_static_aliases_except_the_uploads_logos(): void
    {
        /* Arrange */
        $conf = (string) file_get_contents(ROOT_PATH . '/resources/docker/apache/invoiceplane.conf');

        /* Act / Assert */
        self::assertMatchesRegularExpression('#DocumentRoot\s+\S+/public\s*$#m', $conf);
        self::assertDoesNotMatchRegularExpression('#^\s*Alias\s+/(assets|favicon\.ico|robots\.txt)\b#m', $conf);
        self::assertMatchesRegularExpression('#AliasMatch\s+"\^/uploads/\(\[\^/\]\+\\\\\.\(\?:png\|jpe\?g\|gif\|svg\|webp\)\)\$"#', $conf);
        foreach (['archive', 'customer_files', 'import', 'temp'] as $private) {
            self::assertMatchesRegularExpression('#<Directory\s+\S+/uploads/' . $private . '>\s*Require all denied#', $conf);
        }
    }
}
